 85	const d = (value: Decimal.Value) => new Decimal(value);
 86	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
 87	const share = (part: Decimal, whole: Decimal) => (whole.isZero() ? "0" : out(part.div(whole)));
