 91	function canonicalInput(input: z.infer<typeof debtLedgerInputSchema>) {
 92	  return {...input, rows: [...input.rows].sort((a, b) => a.id.localeCompare(b.id)), schedule: [...input.schedule].sort((a, b) => a.period.localeCompare(b.period))};
