 95	export function buildDebtLedger(raw: DebtLedgerInput): DebtLedgerOutput {
 96	  const input = canonicalInput(debtLedgerInputSchema.parse(raw));
 97	  const rows = input.source === "release_only" ? [] : input.rows;
 98	  const gross = rows.reduce((sum, row) => sum.plus(row.balance), d(0));
 99	  const grossBeforeContra = rows.filter((row) => !row.contra).reduce((sum, row) => sum.plus(row.balance), d(0));
100	
101	  const blockReasons: string[] = [];
102	  if (input.source === "release_only") blockReasons.push("only a release is in the base; a ledger needs the debt note of the financial statements, so no row is produced");
103	  if (input.source === "note" && rows.length === 0 && !input.noDebtEvidence) blockReasons.push("no rows and no evidence that the company has no onerous debt");
104	
105	  let reconciliation: DebtLedgerOutput["reconciliation"] = {state: "not_possible", balanceSheetTotal: null, difference: null, tolerance: input.tolerance, anchor: null};
106	  if (input.balanceSheet && rows.length > 0) {
107	    const total = d(input.balanceSheet.current).plus(input.balanceSheet.nonCurrent);
108	    const difference = gross.minus(total);
109	    const within = difference.abs().lte(input.tolerance);
110	    reconciliation = {state: within ? "reconciled" : "difference", balanceSheetTotal: out(total), difference: out(difference), tolerance: input.tolerance, anchor: input.balanceSheet.anchor};
111	    if (!within) blockReasons.push(`ledger total ${out(gross)} differs from the balance sheet ${out(total)} by ${out(difference)}, above the tolerance ${input.tolerance}`);
112	  } else if (rows.length > 0) {
113	    blockReasons.push("no balance sheet totals in the base: the ledger cannot be reconciled");
114	  }
115	
116	  let schedule: DebtLedgerOutput["schedule"] = null;
117	  if (input.schedule.length > 0 && rows.length > 0) {
118	    const total = input.schedule.reduce((sum, period) => sum.plus(period.amount), d(0));
119	    const matchesGross = total.eq(gross);
120	    schedule = {periods: input.schedule.map((period) => ({period: period.period, amount: out(d(period.amount)), shareOfGross: share(d(period.amount), gross)})), total: out(total), matchesGross, anchor: input.scheduleAnchor ?? null};
121	    if (!matchesGross) blockReasons.push(`schedule total ${out(total)} differs from the ledger total ${out(gross)}`);
122	  }
123	
124	  let netDebtViews: DebtLedgerOutput["netDebtViews"] = {releaseDefinitionRecalculated: null, contractual: null, releaseReported: null};
125	  if (input.cash && rows.length > 0) {
126	    const cash = d(input.cash.cashAndEquivalents);
127	    const investments = d(input.cash.financialInvestments);
128	    const derivativeAssets = d(input.cash.derivativeAssets);
129	    const derivativeLiabilities = d(input.cash.derivativeLiabilities);
130	    const recalculated = gross.minus(cash).minus(investments);
131	    const contractual = gross.plus(derivativeLiabilities).minus(derivativeAssets).minus(cash).minus(investments);
132	    netDebtViews = {
133	      releaseDefinitionRecalculated: {
134	        value: out(recalculated),
135	        definition: "gross debt minus cash and equivalents minus financial investments, recalculated from the statements with the release's definition",
136	        definitionSource: input.releaseNetDebt?.anchor ?? null,
137	        components: {grossDebt: out(gross), cashAndEquivalents: out(cash), financialInvestments: out(investments)},
138	        componentAnchors: {cashAndEquivalents: input.cash.anchors.cash, financialInvestments: input.cash.anchors.cash},
139	      },
140	      contractual: {
141	        value: out(contractual),
142	        definition: "gross debt plus derivative liabilities minus derivative assets minus cash and equivalents minus financial investments, per the indenture definition",
143	        definitionSource: input.contractualDefinitionAnchor ?? null,
144	        components: {grossDebt: out(gross), derivativeLiabilities: out(derivativeLiabilities), derivativeAssets: out(derivativeAssets), cashAndEquivalents: out(cash), financialInvestments: out(investments)},
145	        componentAnchors: {derivativeLiabilities: input.cash.anchors.derivatives, derivativeAssets: input.cash.anchors.derivatives, cashAndEquivalents: input.cash.anchors.cash, financialInvestments: input.cash.anchors.cash},
146	      },
147	      releaseReported: input.releaseNetDebt ? {value: out(d(input.releaseNetDebt.value)), differenceToRecalculated: out(d(input.releaseNetDebt.value).minus(recalculated)), anchor: input.releaseNetDebt.anchor} : null,
148	    };
149	  }
150	
151	  const group = (key: (row: (typeof rows)[number]) => string) => {
152	    const map = new Map<string, {balance: Decimal; rows: string[]}>();
153	    for (const row of rows) {
154	      if (row.contra) continue;
155	      const entry = map.get(key(row)) ?? {balance: d(0), rows: []};
156	      entry.balance = entry.balance.plus(row.balance);
157	      entry.rows.push(row.id);
158	      map.set(key(row), entry);
159	    }
160	    return [...map.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([label, entry]) => ({label, balance: out(entry.balance), shareOfGrossBeforeContra: share(entry.balance, grossBeforeContra), rows: entry.rows}));
161	  };
162	
163	  const uncoveredTerms: DebtLedgerOutput["uncoveredTerms"] = [];
164	  for (const row of rows) {
165	    if (row.contra) continue;
166	    const missing: Array<DebtLedgerOutput["uncoveredTerms"][number]["field"]> = [];
167	    if (row.indexer === "unknown") missing.push("indexer");
168	    if (row.spread === undefined || row.spread === null) missing.push("spread");
169	    if (!row.maturity) missing.push("maturity");
170	    if (row.guarantee === undefined || row.guarantee === null) missing.push("guarantee");
171	    if (row.lender === undefined || row.lender === null) missing.push("lender");
172	    for (const field of missing) uncoveredTerms.push({rowId: row.id, field, state: "insufficient_evidence", reason: row.anchors.terms ? `${field} not stated by ${row.anchors.terms.document}` : `no source in the base states the ${field} of ${row.instrument}${row.series ? ` ${row.series}` : ""}`});
173	  }
174	
175	  const state: DebtLedgerOutput["state"] = input.source === "release_only" ? "incomplete" : rows.length === 0 ? "empty" : blockReasons.length > 0 ? "blocked" : "complete";
176	  const body = {
177	    schemaVersion: "method.build-debt-ledger.v2" as const,
178	    referenceDate: input.referenceDate,
179	    unit: input.unit,
180	    source: input.source,
181	    state,
182	    blockReasons,
183	    ledgerRows: rows.map((row) => ({
184	      id: row.id, instrument: row.instrument, series: row.series ?? null, balance: out(d(row.balance)), currency: row.currency, indexer: row.indexer,
185	      spread: row.spread ?? null, maturity: row.maturity ?? null, guarantee: row.guarantee ?? null, lender: row.lender ?? null, contra: row.contra,
186	      anchors: {balance: row.anchors.balance, terms: row.anchors.terms ?? null},
187	    })),
188	    grossDebt: out(gross),
189	    grossDebtBeforeContra: out(grossBeforeContra),
190	    reconciliation,
191	    schedule,
192	    netDebtViews,
193	    byIndexer: group((row) => row.indexer).map(({label, ...rest}) => ({indexer: label, ...rest})),
194	    byCurrency: group((row) => row.currency).map(({label, ...rest}) => ({currency: label, ...rest})),
195	    uncoveredTerms,
196	  };
197	  return {...body, trace: {calculations: ["financial.debt_ledger_balance", "financial.debt_views", "financial.maturity_buckets", "financial.debt_grouping"], inputFingerprint: fingerprint(input), outputFingerprint: fingerprint(body)}};
