 48	/** Deterministic permutation, different at every step, so consistency is proven beyond one reversal. */
 49	const permute = <T>(items: T[], seed: number): T[] => {
 50	  const copy = [...items];
 51	  let state = seed;
 52	  for (let index = copy.length - 1; index > 0; index -= 1) {
 53	    state = (state * 1103515245 + 12345) % 2147483648;
 54	    const swap = state % (index + 1);
 55	    [copy[index], copy[swap]] = [copy[swap]!, copy[index]!];
 56	  }
 57	  return copy;
 58	};
